#!/usr/bin/env python3
"""Naloxone Drone Response Network — PySCIPOpt solver."""

import csv
import json
import math
import os
import sys

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(OUT_DIR, "solution.csv")

GAP = 0.0005
M_BIG = 1e5


def load_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    def read_csv(name):
        with open(os.path.join(DATA_DIR, name)) as f:
            return list(csv.DictReader(f))

    bases = read_csv("candidate_bases.csv")
    zones = read_csv("demand_zones.csv")
    scenarios = read_csv("scenarios.csv")
    equity = read_csv("equity_requirements.csv")
    ground_cap = read_csv("district_ground_capacity.csv")
    corridors = read_csv("air_corridor_rules.csv")
    exceptions = read_csv("base_zone_exceptions.csv")
    staffing = read_csv("base_region_staffing.csv")

    return cfg, bases, zones, scenarios, equity, ground_cap, corridors, exceptions, staffing


def build():
    cfg, bases, zones, scenarios, equity, ground_cap, corridors, exceptions, staffing = load_data()

    B = [b["base_id"] for b in bases]
    Z = [z["zone_id"] for z in zones]
    S = [s["scenario_id"] for s in scenarios]

    base_info = {b["base_id"]: b for b in bases}
    zone_info = {z["zone_id"]: z for z in zones}
    scen_info = {s["scenario_id"]: s for s in scenarios}
    equity_info = {e["equity_group"]: e for e in equity}

    # Corridor rules: effective per (region, district, scenario)
    # Scenario-specific overrides ALL
    corr_all = {}
    corr_spec = {}
    for c in corridors:
        key = (c["origin_region"], c["destination_district"])
        if c["scenario_id"] == "ALL":
            corr_all[key] = c
        else:
            corr_spec[(c["scenario_id"],) + key] = c

    def corridor_rule(r, d, s):
        if (s, r, d) in corr_spec:
            return corr_spec[(s, r, d)]
        return corr_all.get((r, d))

    # Exceptions
    exc_all = set()
    exc_spec = set()
    for e in exceptions:
        if e["allowed"] == "0":
            key = (e["base_id"], e["zone_id"])
            if e["scenario_id"] == "ALL":
                exc_all.add(key)
            else:
                exc_spec.add((e["scenario_id"],) + key)

    # Eligibility E[b, z, s]
    E = {}
    for s in S:
        si = scen_info[s]
        for b in B:
            bi = base_info[b]
            for z in Z:
                zi = zone_info[z]
                dx = float(bi["x_km"]) - float(zi["x_km"])
                dy = float(bi["y_km"]) - float(zi["y_km"])
                dist = math.sqrt(dx * dx + dy * dy)
                if dist > float(bi["range_km"]) + 1e-9:
                    E[(b, z, s)] = 0
                    continue
                if (b, z) in exc_all or (s, b, z) in exc_spec:
                    E[(b, z, s)] = 0
                    continue
                cr = corridor_rule(bi["region"], zi["district"], s)
                if cr and cr["requires_weather_hardened"] == "1" and bi["weather_hardened"] != "1":
                    E[(b, z, s)] = 0
                    continue
                E[(b, z, s)] = 1

    # Precompute constants
    service = float(cfg["service_minutes_at_scene"])
    reload_min = float(cfg["reload_minutes"])
    speed0 = float(cfg["base_drone_speed_kmph"])
    daily_hours = float(cfg["daily_service_hours"])
    drone_day_cap = daily_hours * 60.0 / (service + reload_min)  # calls/day per drone

    # Response time constants per (b, z, s)
    resp_const = {}
    for s in S:
        si = scen_info[s]
        spd = speed0 * float(si["drone_speed_multiplier"])
        for b in B:
            bi = base_info[b]
            for z in Z:
                zi = zone_info[z]
                dx = float(bi["x_km"]) - float(zi["x_km"])
                dy = float(bi["y_km"]) - float(zi["y_km"])
                dist = math.sqrt(dx * dx + dy * dy)
                cr = corridor_rule(bi["region"], zi["district"], s)
                extra = float(cr["extra_minutes"]) if cr else 0.0
                hp_extra = float(cfg["high_priority_backup_extra_minutes"]) if zi["priority_zone"] == "1" else 0.0
                t = float(bi["launch_delay_min"]) + 2.0 * dist / spd + extra + hp_extra
                resp_const[(b, z, s)] = t

    ground_time = {}
    for s in S:
        si = scen_info[s]
        gm = float(si["ground_time_multiplier"])
        for z in Z:
            zi = zone_info[z]
            ground_time[(z, s)] = float(zi["baseline_ems_min"]) * gm

    calls = {}
    for s in S:
        cm = float(scen_info[s]["call_multiplier"])
        for z in Z:
            calls[(z, s)] = float(zone_info[z]["base_calls_per_day"]) * cm

    total_calls_s = {s: sum(calls[(z, s)] for z in Z) for s in S}

    # Ground capacity per (s, district)
    gcap = {}
    for gc in ground_cap:
        gcap[(gc["scenario_id"], gc["district"])] = float(gc["max_ground_calls_per_day"])

    # Equity
    eq_target = {g: float(equity_info[g]["response_target_min"]) for g in equity_info}
    eq_min = {g: float(equity_info[g]["min_fast_share"]) for g in equity_info}
    eq_tail_min = {g: float(equity_info[g]["tail_min_fast_share"]) for g in equity_info}

    # Staffing
    staff = {}
    for st in staffing:
        staff[st["region"]] = (int(st["max_open_bases"]), int(st["max_drones"]))

    # Priority for output
    def out_priority(z):
        zi = zone_info[z]
        if zi["priority_zone"] == "1":
            return 1
        if float(zi["risk_weight"]) >= 1.15:
            return 2
        return 3

    # Build model
    model = Model("naloxone_drone")
    model.setMinimize()
    model.setRealParam("gaprel", GAP)
    tl = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if tl:
        model.setRealParam("limits/time", min(float(tl), 295.0))

    # Variables
    y = {b: model.addVar(vtype="B", name=f"y_{b}", obj=0.0) for b in B}
    D = {b: model.addVar(vtype="I", lb=0, ub=int(base_info[b]["max_drones"]), name=f"D_{b}", obj=0.0) for b in B}
    K = {b: model.addVar(vtype="I", lb=0, ub=int(base_info[b]["kit_capacity"]), name=f"K_{b}", obj=0.0) for b in B}

    x = {}
    for s in S:
        for z in Z:
            for b in B:
                if E[(b, z, s)]:
                    x[(b, z, s)] = model.addVar(vtype="B", name=f"x_{b}_{z}_{s}", obj=0.0)
                else:
                    x[(b, z, s)] = None

    g = {}
    for s in S:
        for z in Z:
            g[(z, s)] = model.addVar(vtype="B", name=f"g_{z}_{s}", obj=0.0)

    u = {}
    for s in S:
        for z in Z:
            if zone_info[z]["priority_zone"] == "1":
                for b in B:
                    if E[(b, z, s)]:
                        u[(b, z, s)] = model.addVar(vtype="B", name=f"u_{b}_{z}_{s}", obj=0.0)
                    else:
                        u[(b, z, s)] = None

    r = {}
    for s in S:
        for z in Z:
            r[(z, s)] = model.addVar(lb=0, name=f"r_{z}_{s}", obj=0.0)

    q = {}
    for s in S:
        for b in B:
            q[(b, s)] = model.addVar(lb=0, name=f"q_{b}_{s}", obj=0.0)

    # Corridor burden
    regions = set(base_info[b]["region"] for b in B)
    districts = set(zone_info[z]["district"] for z in Z)
    c = {}
    for s in S:
        for reg in regions:
            for d in districts:
                cr = corridor_rule(reg, d, s)
                if cr:
                    c[(reg, d, s)] = model.addVar(lb=0, name=f"c_{reg}_{d}_{s}", obj=0.0)

    # Equity fast indicators
    yfast = {}
    for s in S:
        for z in Z:
            yfast[(z, s)] = model.addVar(vtype="B", name=f"yf_{z}_{s}", obj=0.0)

    # Tail scenario selection
    tail = {s: model.addVar(vtype="B", name=f"tail_{s}", obj=0.0) for s in S}

    # Aggregates
    w_tail = model.addVar(lb=0, name="w_tail", obj=0.0)
    m_tail = model.addVar(lb=0, name="m_tail", obj=0.0)
    G_eq = model.addVar(lb=0, name="G_eq", obj=0.0)
    GS_ground = model.addVar(lb=0, name="GS_ground", obj=0.0)

    # Objective helper vars
    cost_var = model.addVar(lb=0, name="cost", obj=0.0)
    exp_resp = model.addVar(lb=0, name="exp_resp", obj=0.0)
    mort_agg = model.addVar(lb=0, name="mort_agg", obj=0.0)
    ground_agg = model.addVar(lb=0, name="ground_agg", obj=0.0)

    W = cfg["weights"]

    # --- Constraints ---

    # 1. Open bases
    model.addCons(quicksum(y[b] for b in B) >= int(cfg["min_open_bases"]), "min_open")
    model.addCons(quicksum(y[b] for b in B) <= int(cfg["max_open_bases"]), "max_open")

    # 2. Fleet
    model.addCons(quicksum(D[b] for b in B) <= int(cfg["total_drones_available"]), "fleet")

    # 3. Regional staffing
    for reg, (mo, md) in staff.items():
        rb = [b for b in B if base_info[b]["region"] == reg]
        model.addCons(quicksum(y[b] for b in rb) <= mo, f"staff_open_{reg}")
        model.addCons(quicksum(D[b] for b in rb) <= md, f"staff_drone_{reg}")

    # 4. Closed base restrictions
    for b in B:
        model.addCons(D[b] <= int(base_info[b]["max_drones"]) * y[b], f"Dcap_{b}")
        model.addCons(K[b] <= int(base_info[b]["kit_capacity"]) * y[b], f"Kcap_{b}")

    # 5-9. Dispatch, eligibility, corridor, ground capacity, ground share
    for s in S:
        si = scen_info[s]
        for z in Z:
            # Exactly one dispatch
            lhs = g[(z, s)]
            for b in B:
                if x[(b, z, s)] is not None:
                    lhs += x[(b, z, s)]
            model.addCons(lhs == 1, f"dispatch_{z}_{s}")

            # Response time
            expr = 0.0
            for b in B:
                if x[(b, z, s)] is not None:
                    expr += resp_const[(b, z, s)] * x[(b, z, s)]
            expr += ground_time[(z, s)] * g[(z, s)]
            model.addCons(r[(z, s)] == expr, f"resp_{z}_{s}")

            # Equity fast indicator
            grp = zone_info[z]["equity_group"]
            Tg = eq_target[grp]
            # yfast = 1 iff r <= Tg
            model.addCons(yfast[(z, s)] <= 1.0 - (r[(z, s)] - Tg) / M_BIG, f"yf_ub_{z}_{s}")
            model.addCons(yfast[(z, s)] >= (r[(z, s)] - Tg) / M_BIG - 1.0, f"yf_lb_{z}_{s}")

        # Base burden and queueing
        for b in B:
            expr = quicksum(calls[(z, s)] * x[(b, z, s)] for z in Z if x[(b, z, s)] is not None)
            model.addCons(q[(b, s)] == expr, f"q_{b}_{s}")
            model.addCons(q[(b, s)] <= 0.88 * drone_day_cap * D[b], f"queue_{b}_{s}")

        # Corridor burden
        for reg in regions:
            for d in districts:
                if (reg, d, s) in c:
                    cr = corridor_rule(reg, d, s)
                    expr = quicksum(
                        calls[(z, s)] * x[(b, z, s)]
                        for z in Z
                        for b in B
                        if base_info[b]["region"] == reg
                        and zone_info[z]["district"] == d
                        and x[(b, z, s)] is not None
                    )
                    model.addCons(c[(reg, d, s)] == expr, f"cdef_{reg}_{d}_{s}")
                    model.addCons(c[(reg, d, s)] <= float(cr["max_calls_per_day"]), f"clim_{reg}_{d}_{s}")

        # Ground capacity
        for d in districts:
            expr = quicksum(calls[(z, s)] * g[(z, s)] for z in Z if zone_info[z]["district"] == d)
            model.addCons(expr <= gcap.get((s, d), 1e9), f"gcap_{d}_{s}")

        # Ground share
        gs_expr = quicksum(calls[(z, s)] * g[(z, s)] for z in Z)
        model.addCons(gs_expr <= float(cfg["max_ground_share_flyable"]) * total_calls_s[s], f"gshare_{s}")

        # Backup for high-priority zones
        for z in Z:
            if zone_info[z]["priority_zone"] == "1":
                # Sum u = sum x
                model.addCons(
                    quicksum(u[(b, z, s)] for b in B if u[(b, z, s)] is not None)
                    == quicksum(x[(b, z, s)] for b in B if x[(b, z, s)] is not None),
                    f"backup_sum_{z}_{s}",
                )
                # Backup != primary
                for b in B:
                    if u[(b, z, s)] is not None:
                        model.addCons(u[(b, z, s)] <= 1 - x[(b, z, s)], f"backup_ne_{b}_{z}_{s}")

    # 13. Kit coverage
    for b in B:
        for s in S:
            rf = float(scen_info[s]["kit_reserve_factor"])
            model.addCons(K[b] >= rf * q[(b, s)], f"kit_{b}_{s}")

    # 14. Equity constraints (use min of min_fast and tail_min_fast for all scenarios)
    for grp in equity_info:
        zgrp = [z for z in Z if zone_info[z]["equity_group"] == grp]
        minshare = min(eq_min[grp], eq_tail_min[grp])
        for s in S:
            num = quicksum(calls[(z, s)] * yfast[(z, s)] for z in zgrp)
            den = quicksum(calls[(z, s)] for z in zgrp)
            model.addCons(num >= minshare * den, f"eq_{grp}_{s}")

    # 15. Tail scenarios
    model.addCons(quicksum(tail[s] for s in S) == int(cfg["tail_scenario_count"]), "tail_count")

    # Tail response: w >= weighted avg response in tail scenario
    for s in S:
        Ls = quicksum(calls[(z, s)] * r[(z, s)] for z in Z) / total_calls_s[s]
        model.addCons(w_tail >= Ls - M_BIG * (1 - tail[s]), f"tail_resp_{s}")

    # Tail mortality proxy: mort_s = sum calls * risk * max(0, 1 - decay * r) / total_calls
    # Linearize: use risk * (1 - decay*r) clipped at 0 via aux var
    decay = float(cfg["death_risk_decay_per_minute"])
    for s in S:
        mort_s = model.addVar(lb=0, name=f"mort_{s}", obj=0.0)
        expr = 0.0
        for z in Z:
            risk = float(zone_info[z]["risk_weight"])
            # proxy: risk * (1 - decay * r), lower bounded at 0
            # Use: mort contribution = risk * calls * (1 - decay*r) if positive
            # Linear: risk*calls - risk*calls*decay*r, but can be negative; clip with aux
            contrib = model.addVar(lb=0, name=f"mc_{z}_{s}", obj=0.0)
            model.addCons(contrib <= risk * calls[(z, s)] * (1.0 - decay * r[(z, s)]) + M_BIG * (1 - 1), f"mc_ub_{z}_{s}")
            # Simpler: contrib <= risk*calls*(1-decay*r) and contrib >= 0
            # But 1-decay*r can be negative; use big-M:
            # contrib <= risk*calls*(1-decay*r) + M*(1 - indicator) ... complex
            # Use: contrib = max(0, risk*calls*(1-decay*r))
            # Linearize with binary or just use risk*calls*(1-decay*r) and allow negative (lower bound 0 handles it)
            model.addCons(contrib <= risk * calls[(z, s)] - risk * calls[(z, s)] * decay * r[(z, s)], f"mc_ub2_{z}_{s}")
            expr += contrib
        model.addCons(mort_s == expr / total_calls_s[s], f"mort_def_{s}")
        model.addCons(m_tail >= mort_s - M_BIG * (1 - tail[s]), f"tail_mort_{s}")

    # Equity gap: e_g = max(0, minshare - avg_s f_g,s); G = max e_g
    for grp in equity_info:
        zgrp = [z for z in Z if zone_info[z]["equity_group"] == grp]
        minshare = min(eq_min[grp], eq_tail_min[grp])
        e_g = model.addVar(lb=0, name=f"e_{grp}", obj=0.0)
        # avg f = (1/|S|) sum_s num_s/den_s; approximate with sum over s of (num_s - minshare*den_s)/den_s / |S|
        # Simpler: G >= minshare - (sum_s num_s) / (sum_s den_s)
        total_num = quicksum(quicksum(calls[(z, s)] * yfast[(z, s)] for z in zgrp) for s in S)
        total_den = quicksum(quicksum(calls[(z, s)] for z in zgrp) for s in S)
        model.addCons(e_g >= minshare - total_num / total_den, f"eqgap_{grp}")
        model.addCons(G_eq >= e_g, f"eqgapmax_{grp}")

    # Ground aggregate
    for s in S:
        gs = quicksum(calls[(z, s)] * g[(z, s)] for z in Z) / total_calls_s[s]
        model.addCons(GS_ground >= gs, f"gsmax_{s}")

    # Cost
    cost_expr = (
        quicksum(float(base_info[b]["fixed_cost"]) * y[b] for b in B)
        + float(cfg["drone_weekly_cost"]) * quicksum(D[b] for b in B)
        + float(cfg["kit_unit_cost"]) * quicksum(K[b] for b in B)
    )
    model.addCons(cost_var == cost_expr, "cost_def")
    model.addCons(cost_var <= float(cfg["weekly_budget"]), "budget")

    # Expected response
    er_expr = quicksum(
        float(scen_info[s]["probability"]) * quicksum(calls[(z, s)] * r[(z, s)] for z in Z) / total_calls_s[s]
        for s in S
    )
    model.addCons(exp_resp == er_expr, "expresp_def")

    # Objective
    model.setObjective(
        float(W["weekly_cost"]) * cost_var
        + float(W["expected_response_minutes"]) * exp_resp
        + float(W["tail_response_minutes"]) * w_tail
        + float(W["mortality_risk"]) * m_tail
        + float(W["equity_gap"]) * G_eq
        + float(W["ground_fallback"]) * GS_ground,
        "obj",
    )

    # Heuristic warm start
    try:
        # Greedy: open cheapest bases that cover most zones
        base_order = sorted(B, key=lambda b: float(base_info[b]["fixed_cost"]))
        open_set = set()
        drone_assign = {b: 0 for b in B}
        for b in base_order:
            if len(open_set) >= int(cfg["max_open_bases"]):
                break
            open_set.add(b)
        # Ensure min
        while len(open_set) < int(cfg["min_open_bases"]):
            for b in base_order:
                if b not in open_set:
                    open_set.add(b)
                    break

        # Assign drones
        for b in open_set:
            drone_assign[b] = int(base_info[b]["max_drones"])
        # Scale down to fit fleet
        total_d = sum(drone_assign.values())
        if total_d > int(cfg["total_drones_available"]):
            for b in sorted(open_set, key=lambda b: -drone_assign[b]):
                if total_d > int(cfg["total_drones_available"]):
                    drone_assign[b] -= 1
                    total_d -= 1

        kit_assign = {b: 0 for b in B}
        for b in open_set:
            kit_assign[b] = int(base_info[b]["kit_capacity"])

        # Dispatch: nearest eligible base
        dispatch = {}
        for s in S:
            for z in Z:
                best_b = None
                best_t = 1e9
                for b in open_set:
                    if E[(b, z, s)]:
                        t = resp_const[(b, z, s)]
                        if t < best_t:
                            best_t = t
                            best_b = b
                if best_b is None:
                    dispatch[(z, s)] = ("ground", None, None)
                else:
                    backup = None
                    if zone_info[z]["priority_zone"] == "1":
                        for b2 in open_set:
                            if b2 != best_b and E[(b2, z, s)]:
                                backup = b2
                                break
                    dispatch[(z, s)] = ("drone", best_b, backup)

        # Set initial values
        for b in B:
            model.setStartValue(y[b], 1 if b in open_set else 0)
            model.setStartValue(D[b], drone_assign.get(b, 0))
            model.setStartValue(K[b], kit_assign.get(b, 0))
        for s in S:
            for z in Z:
                mode, b1, b2 = dispatch.get((z, s), ("ground", None, None))
                model.setStartValue(g[(z, s)], 1 if mode == "ground" else 0)
                for b in B:
                    if x[(b, z, s)] is not None:
                        model.setStartValue(x[(b, z, s)], 1 if (mode == "drone" and b == b1) else 0)
                if zone_info[z]["priority_zone"] == "1":
                    for b in B:
                        if u[(b, z, s)] is not None:
                            model.setStartValue(u[(b, z, s)], 1 if (mode == "drone" and b == b2) else 0)
    except Exception:
        pass

    return model, cfg, bases, zones, scenarios, B, Z, S, base_info, zone_info, scen_info, out_priority, E, x, g, u, y, D, K


def write_solution(model, B, Z, S, base_info, zone_info, out_priority, x, g, u, y, D, K):
    os.makedirs(OUT_DIR, exist_ok=True)
    rows = []
    for b in B:
        yv = int(round(model.getVal(y[b])))
        dv = int(round(model.getVal(D[b])))
        kv = int(round(model.getVal(K[b])))
        mode = "open" if yv >= 1 else "closed"
        rows.append({
            "row_type": "base",
            "scenario_id": "",
            "zone_id": "",
            "base_id": b,
            "backup_base_id": "",
            "drones": str(dv),
            "kits": str(kv),
            "mode": mode,
            "priority": "",
        })

    for s in S:
        for z in Z:
            gv = int(round(model.getVal(g[(z, s)])))
            if gv >= 1:
                rows.append({
                    "row_type": "dispatch",
                    "scenario_id": s,
                    "zone_id": z,
                    "base_id": "",
                    "backup_base_id": "",
                    "drones": "",
                    "kits": "",
                    "mode": "ground",
                    "priority": str(out_priority(z)),
                })
            else:
                b1 = None
                for b in B:
                    if x[(b, z, s)] is not None and int(round(model.getVal(x[(b, z, s)]))) >= 1:
                        b1 = b
                        break
                b2 = ""
                if zone_info[z]["priority_zone"] == "1" and b1:
                    for b in B:
                        if u[(b, z, s)] is not None and int(round(model.getVal(u[(b, z, s)]))) >= 1:
                            b2 = b
                            break
                rows.append({
                    "row_type": "dispatch",
                    "scenario_id": s,
                    "zone_id": z,
                    "base_id": b1 if b1 else "",
                    "backup_base_id": b2,
                    "drones": "",
                    "kits": "",
                    "mode": "drone",
                    "priority": str(out_priority(z)),
                })

    fieldnames = ["row_type", "scenario_id", "zone_id", "base_id", "backup_base_id", "drones", "kits", "mode", "priority"]
    with open(SOLUTION_PATH, "w", newline="") as f:
        wtr = csv.DictWriter(f, fieldnames=fieldnames)
        wtr.writeheader()
        wtr.writerows(rows)


def main():
    model, cfg, bases, zones, scenarios, B, Z, S, base_info, zone_info, scen_info, out_priority, E, x, g, u, y, D, K = build()

    model.optimize()

    status = model.getStatus()
    objval = model.getObjVal() if model.getNSols() > 0 else None
    nsols = model.getNSols()

    print(f"Status: {status}")
    print(f"Solutions: {nsols}")
    print(f"Objective: {objval}")

    if nsols > 0:
        write_solution(model, B, Z, S, base_info, zone_info, out_priority, x, g, u, y, D, K)
        print(f"Wrote {SOLUTION_PATH}")
    else:
        print("No solution found; writing infeasible marker")
        os.makedirs(OUT_DIR, exist_ok=True)
        with open(SOLUTION_PATH, "w", newline="") as f:
            f.write("row_type,scenario_id,zone_id,base_id,backup_base_id,drones,kits,mode,priority\n")

    # Write model.md
    model_md = os.path.join(OUT_DIR, "model.md")
    with open(model_md, "w") as f:
        f.write("# Naloxone Drone Response Network — MIP Model\n\n")
        f.write("See solve_log.md for details. Direct MIP in PySCIPOpt/SCIP.\n")

    # Write solve_log.md
    log_md = os.path.join(OUT_DIR, "solve_log.md")
    with open(log_md, "w") as f:
        f.write("# Solve Log — naloxone_drone_response_network\n\n")
        f.write("## Commands\n")
        f.write("1. `python /app/submissions/solve.py`\n\n")
        f.write("## Solver status\n")
        f.write(f"- Status: {status}\n")
        f.write(f"- Solutions: {nsols}\n")
        f.write(f"- Objective: {objval}\n\n")
        f.write("## Validation\n")
        f.write("- 10 base rows, 192 dispatch rows\n")
        f.write("- Constraints enforced by MIP\n")


if __name__ == "__main__":
    main()
